// Generated by OpenFlex Neo MXML Compiler
// MXML -> Web Components with Reactivity
// Browser Version

const count = new Signal(0);

function increment() {
  count.value = count.value + 1;
}

// Application Component
class AppComponent extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();

    // Set up reactive effects
    this.setupReactivity();
  }

  render() {
    this.shadowRoot.innerHTML = `
      <style>
        .vbox {
          display: flex;
          flex-direction: column;
          gap: 20px;
          align-items: center;
          padding: 20px;
        }

        span {
          font-size: 1.2em;
          color: #333;
        }

        button {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          border: none;
          padding: 12px 32px;
          font-size: 1.1em;
          border-radius: 8px;
          cursor: pointer;
          transition: transform 0.2s, box-shadow 0.2s;
          font-weight: 600;
        }

        button:hover {
          transform: translateY(-2px);
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
        }

        button:active {
          transform: translateY(0);
        }

        #binding_0 {
          font-size: 2em;
          font-weight: bold;
          color: #667eea;
        }
      </style>
      <div class='application'>
        <div class='vbox'>
          <span>Counter Example</span>
          <span id='binding_0'></span>
          <button id='btn_1'>Increment</button>
        </div>
      </div>
    `;

    // Attach event handlers
    this.shadowRoot.getElementById('btn_1').onclick = () => increment();
  }

  setupReactivity() {
    // Auto-update DOM when reactive state changes
    createEffect(() => {
      const el = this.shadowRoot.getElementById('binding_0');
      if (el) el.textContent = 'Count: ' + count.value + '';
    });
  }
}

// Register Custom Elements
customElements.define('app-root', AppComponent);
